.screen{position:absolute;inset:0;z-index:3;opacity:0;pointer-events:none;transition:opacity 1s ease}.screen.visible{opacity:1;pointer-events:auto}.menu-top{position:absolute;left:5.2%;right:5.2%;top:5.4%;display:flex;align-items:center;gap:12px;color:#c5c6c1;font:10px 'DM Mono',monospace;letter-spacing:.2em}.brand-mark{display:grid;place-items:center;width:25px;height:25px;border:1px solid rgba(220,221,210,.44);font:500 14px 'Oswald',sans-serif;color:#d7ad79}.menu-version{margin-left:auto;color:#888982}.menu-copy{position:absolute;left:11.5%;top:20%;width:min(410px,40vw)}.eyebrow{display:flex;align-items:center;gap:10px;color:#d4a674;font:10px 'DM Mono',monospace;letter-spacing:.19em}.eyebrow i,.rec-indicator i{width:6px;height:6px;background:#d89360;border-radius:50%;box-shadow:0 0 12px #da754c}.menu-copy h1{font:500 clamp(82px,11vw,154px)/.79 'Oswald',sans-serif;letter-spacing:-.04em;margin:28px 0 21px;color:#ede8df;text-shadow:0 3px 24px #151717}.menu-copy h1 span{color:#d2a574}.tagline{font:italic 16px Georgia,serif;color:#b9b5ad;margin:0 0 27px}.menu-rule{height:1px;width:62px;background:#b88759;margin:0 0 20px}.intro-copy{font-size:13px;line-height:1.75;color:#b0b0a9;margin:0 0 27px}.primary-button{display:flex;align-items:center;justify-content:space-between;width:254px;height:53px;padding:0 17px;border:1px solid #d5a574;background:#c39668;color:#111310;font:500 11px 'DM Mono',monospace;letter-spacing:.14em;cursor:pointer;transition:background .2s,transform .2s,border .2s}.primary-button:hover{background:#e2b783;transform:translateY(-2px);border-color:#f0c99d}.primary-button b{font-size:18px;font-weight:400}.menu-foot{margin-top:19px;color:#8f918d;font:9px 'DM Mono',monospace;letter-spacing:.09em}.menu-foot span,.controls-hint span,.look-hint span{color:#d49b6a;padding:0 5px}.menu-location{position:absolute;left:5.2%;bottom:6%;display:flex;gap:21px;color:#898c88;font:9px 'DM Mono',monospace;letter-spacing:.1em}.room-caption{position:absolute;right:5.2%;bottom:6%;display:flex;gap:23px;color:#aaa9a1;font:10px 'DM Mono',monospace;letter-spacing:.14em}.room-caption span:first-child{color:#d4a674}
#hud{position:absolute;inset:0;z-index:4;pointer-events:none;opacity:1;transition:opacity .4s}#hud.hidden,.hidden{display:none!important}.hud-top{position:absolute;top:5.4%;left:5.2%;right:5.2%;display:flex;justify-content:space-between;align-items:flex-start}.mission-card{display:flex;flex-direction:column;gap:7px;padding-left:13px;border-left:1px solid #d09b6c;max-width:380px;text-shadow:0 2px 6px #000}.hud-label{color:#d4a674;font:9px 'DM Mono',monospace;letter-spacing:.16em}.hud-label b{margin-left:7px;color:#85877f;font-weight:400}.mission-card strong{font:500 16px 'DM Sans',sans-serif;color:#eeece5}.mission-card>span:last-child{font-size:11px;color:#a6a8a2}.signal{display:flex;align-items:center;gap:10px;color:#aaa;font:9px 'DM Mono',monospace;letter-spacing:.12em}.signal .hud-label{margin-right:4px}.signal-bars{display:flex;align-items:flex-end;gap:3px;height:13px}.signal-bars i{width:3px;background:#bd9064;height:4px}.signal-bars i:nth-child(2){height:7px}.signal-bars i:nth-child(3){height:10px}.signal-bars i:nth-child(4){height:13px}.signal-bars i:nth-child(5){height:13px;background:#555}
.hud-bottom{position:absolute;bottom:5.1%;left:5.2%;right:5.2%;display:flex;justify-content:space-between;align-items:flex-end}.controls-hint{position:absolute;left:50%;transform:translateX(-50%);bottom:0;white-space:nowrap;color:#a1a39e;font:9px 'DM Mono',monospace;letter-spacing:.09em}.rec-indicator{display:flex;align-items:center;gap:8px;color:#d0d0c8;font:9px 'DM Mono',monospace;letter-spacing:.12em}.rec-indicator i{background:#d76552;box-shadow:0 0 9px #dc5849;animation:pulse 1.7s infinite}.rec-indicator span{margin-left:10px;color:#aaa}.interaction-prompt{position:absolute;bottom:48px;left:50%;transform:translateX(-50%);min-height:44px;text-align:center;color:#e5e0d7;font:11px 'DM Mono',monospace;letter-spacing:.08em;text-shadow:0 2px 8px #000}.interaction-prompt b{display:inline-grid;place-items:center;border:1px solid #d5a574;color:#e3b481;width:23px;height:23px;margin-right:8px;font-weight:400}.toast{position:absolute;left:50%;top:22%;transform:translate(-50%,-10px);opacity:0;padding:12px 17px;border:1px solid rgba(202,160,114,.38);background:rgba(9,12,12,.85);color:#e4d7c6;font:10px 'DM Mono',monospace;letter-spacing:.12em;transition:all .35s}.toast.show{opacity:1;transform:translate(-50%,0)}
.look-hint{position:absolute;z-index:4;bottom:9%;left:50%;transform:translateX(-50%);color:#b4b6b0;font:9px 'DM Mono',monospace;letter-spacing:.12em;text-shadow:0 2px 8px #000;pointer-events:none}.note-modal,.end-screen{position:absolute;inset:0;z-index:10;display:grid;place-items:center;background:rgba(3,5,5,.65);pointer-events:auto;backdrop-filter:blur(4px)}.note-paper{position:relative;width:min(410px,88vw);padding:43px 43px 30px;background:#d6c9ad;color:#2c2a23;box-shadow:0 20px 70px #0009;transform:rotate(-1deg)}.note-paper:before{content:'';position:absolute;inset:10px;border:1px solid #766d5e44;pointer-events:none}.note-paper button{position:absolute;right:19px;top:14px;border:0;background:none;color:#51483b;font-size:23px;cursor:pointer}.note-overline{font:9px 'DM Mono',monospace;letter-spacing:.15em;color:#796e5b}.note-paper h2{font:500 29px 'Oswald',sans-serif;margin:19px 0 15px}.note-paper p{font:14px/1.8 Georgia,serif;white-space:pre-line}.note-signature{display:block;text-align:right;font:italic 14px Georgia,serif;margin-top:22px}.note-continue{text-align:center;margin-top:37px;color:#726856;font:8px 'DM Mono',monospace;letter-spacing:.12em}.end-card{text-align:left;width:min(460px,90vw);padding:52px;background:rgba(13,16,16,.91);border:1px solid #755c43;box-shadow:0 20px 80px #000}.end-card h2{font:500 52px/.96 'Oswald',sans-serif;margin:24px 0;color:#e4d7c4}.end-card p{color:#b4b3ad;font-size:13px;line-height:1.7;margin-bottom:28px}.flash{position:absolute;inset:0;z-index:9;background:#fff2d6;opacity:0;pointer-events:none}.flash.bang{animation:bang .28s ease-out}@keyframes bang{0%{opacity:.42}100%{opacity:0}}@keyframes pulse{50%{opacity:.35}}
