import * as THREE from 'three';
import './style.css';

const canvas = document.querySelector('#scene');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x101514);
scene.fog = new THREE.FogExp2(0x111615, .023);
const camera = new THREE.PerspectiveCamera(72, innerWidth / innerHeight, .08, 100);
camera.rotation.order = 'YXZ';
const player = new THREE.Group();
player.add(camera); scene.add(player);
const clock = new THREE.Clock();
const raycaster = new THREE.Raycaster(); raycaster.far = 4.2;
const center = new THREE.Vector2(0, 0);
const interactables = [];
let activeArea = 'room', started = false, pointerLocked = false, yaw = 0, pitch = 0, flashlightOn = true;
let hasCode = false, doorOpened = false, evidence = 0, entityAlert = false, gameEnded = false;
const keys = new Set();
const $ = (s) => document.querySelector(s);
const ui = { menu: $('#menu-screen'), hud: $('#hud'), prompt: $('#interaction-prompt'), objective: $('#objective'), sub: $('#objective-sub'), toast: $('#toast'), note: $('#note-modal'), noteTitle: $('#note-title'), noteBody: $('#note-body'), look: $('#look-hint'), end: $('#end-screen') };
const mats = {};
function mat(name, color, roughness = .85, extra = {}) { return mats[name] ||= new THREE.MeshStandardMaterial({ color, roughness, ...extra }); }
function box(parent, name, x,y,z, sx,sy,sz, material, opts={}) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz), material);
  mesh.name = name; mesh.position.set(x,y,z); mesh.castShadow = opts.cast ?? true; mesh.receiveShadow = opts.receive ?? true;
  if(opts.ry) mesh.rotation.y=opts.ry; if(opts.rx) mesh.rotation.x=opts.rx;
  parent.add(mesh); return mesh;
}
function sphere(parent,name,x,y,z,r,material,sx=1,sy=1,sz=1){const m=new THREE.Mesh(new THREE.SphereGeometry(r,16,12),material);m.name=name;m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;parent.add(m);return m;}
function cylinder(parent,name,x,y,z,r1,r2,h,material,segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.name=name;m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function light(parent,color,intensity,x,y,z,distance=0){const l=new THREE.PointLight(color,intensity,distance,2);l.position.set(x,y,z);parent.add(l);return l;}
function makeGroup(name){const g=new THREE.Group();g.name=name;scene.add(g);return g;}
function addInteract(mesh,label,action){mesh.userData.label=label;mesh.userData.action=action;interactables.push(mesh);return mesh;}
const room = makeGroup('Safehouse');
const lot = makeGroup('Ashford exterior'); lot.visible=false;
const lab = makeGroup('Sublevel laboratory'); lab.visible=false;
const ambient = new THREE.HemisphereLight(0x9ca9aa,0x151515,.36); scene.add(ambient);
const moon = new THREE.DirectionalLight(0xa6b8bf,.55);moon.position.set(-18,24,12);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);scene.add(moon);
const flashlight = new THREE.SpotLight(0xe5eddd,38,28,Math.PI/7,.4,1.4); flashlight.position.set(0,0,0); flashlight.target.position.set(0,0,-1);camera.add(flashlight,flashlight.target);
const fill = new THREE.PointLight(0x9f7150,1.2,12);camera.add(fill);fill.position.set(0,1,1);

function buildRoom(){
  room.add(new THREE.AmbientLight(0xb2aaa0,.55));
  const warm=light(room,0xffc583,22,-2.5,3.8,1,13); warm.castShadow=true;
  const wall=mat('plaster',0x746e63), floor=mat('wood',0x453b31), dark=mat('dark wood',0x282522), trim=mat('trim',0x302b25), glass=mat('glass',0x18272a,.2,{metalness:.25,emissive:0x102126,emissiveIntensity:.8});
  box(room,'floor',0,-.12,0,12,.24,12,floor); box(room,'ceiling',0,4.8,0,12,.25,12,mat('ceiling',0x3f3d37));
  box(room,'back wall',0,2.4,-5.95,12,4.8,.22,wall);box(room,'left wall',-5.95,2.4,0,.22,4.8,12,mat('left wall',0x5d594f));box(room,'right wall',5.95,2.4,0,.22,4.8,12,wall);
  // front wall has a broad framed picture-window; dark glass remains transparent enough to read as night.
  box(room,'front left wall',-4.5,2.4,5.95,3,4.8,.22,wall);box(room,'front right wall',4.5,2.4,5.95,3,4.8,.22,wall);
  box(room,'window wall top',0,4.1,5.95,6,1.4,.22,wall);box(room,'window wall sill',0,.93,5.95,6,1.86,.22,wall);
  box(room,'window glass',0,2.65,5.95,5.85,2.55,.08,glass,{cast:false});
  for(const x of [-3,0,3])box(room,'window mullion',x,2.65,5.82,.095,2.65,.16,trim);
  for(const y of [1.36,3.94])box(room,'window frame',0,y,5.82,6.12,.13,.18,trim);
  box(room,'couch base',-1.6,.47,1.4,3.15,.62,1.25,mat('couch',0x4c4941),{ry:.05});
  box(room,'couch back',-1.6,1.12,.92,3.15,1.08,.38,mat('couch back',0x57534a));
  for(const x of [-2.7,-1.6,-.5])box(room,'couch cushion',x,.82,1.42,.96,.2,.9,mat('cushion',0x696257));
  for(const x of [-2.82,-.38])for(const z of [1,1.85])box(room,'couch leg',x,.2,z,.12,.4,.12,trim);
  box(room,'coffee table',-1.4,.52,3.05,2,.15,1.05,mat('table',0x302b25));for(const x of [-2.25,-.55])for(const z of [2.7,3.4])box(room,'table leg',x,.25,z,.09,.52,.09,trim);
  box(room,'cardboard box',3,.63,2.4,1.15,1.25,1.05,mat('box',0x796247));box(room,'box top',2.45,1.28,2.4,.06,.03,1.05,mat('box tape',0xb59a70));
  box(room,'shipping crate',4.3,.48,3.8,1.25,.95,1.2,mat('crate',0x514638));box(room,'crate stripe',4.3,.48,3.17,.09,.95,.03,mat('crate stripe',0x927752));
  box(room,'suitcase',3.65,.3,-1.4,1.2,.6,.75,mat('suitcase',0x393d3b));
  // Standing lamp and warm pool of light.
  cylinder(room,'lamp stem',-.1,1.6,-.1,.035,.045,2.9,mat('brass',0x866c4d));cylinder(room,'lamp shade',-.1,3.17,-.1,.25,.42,.48,mat('shade',0xb19a75));light(room,0xffb56b,9,-.1,2.95,-.1,7);
  // Landscape visible through window: pines at either edge, distant decaying industrial building.
  const outside=new THREE.Group();room.add(outside);outside.position.z=6.9;
  const nightSky=mat('night sky',0x10191a), earth=mat('earth',0x202723), factory=mat('distant factory',0x323535), litWin=mat('lit window',0x9c8060,.4,{emissive:0x6e4323,emissiveIntensity:.55});
  box(outside,'distant ground',0,-.35,-14,50,.2,35,earth,{cast:false});box(outside,'factory silhouette',0,1.45,-26,13,3.5,3,factory);box(outside,'factory annex',-8,1,-25,4,2.6,4,mat('factory annex',0x292f2e));
  box(outside,'factory roof',0,3.3,-26,14,.2,3.4,mat('roof',0x242827));
  for(const x of [-4.7,-1.8,2.5,4.2])box(outside,'factory window',x,1.8,-24.43,.55,.75,.03,litWin,{cast:false});
  function pine(x,z,h){cylinder(outside,'pine trunk',x,h*.34,z,.12,.2,h*.68,mat('bark',0x302a22),7);for(let i=0;i<3;i++){const c=new THREE.Mesh(new THREE.ConeGeometry(h*(.29-i*.045),h*.46,7),mat('pine',i===1?0x1d2925:0x25312a));c.position.set(x,h*(.34+i*.19),z);c.castShadow=true;outside.add(c)}}
  for(const [x,z,h] of [[-8,-2,7],[ -11,-9,9],[-7,-15,6],[9,-4,8],[12,-12,10],[7,-19,7],[16,-6,9],[-15,-4,8]])pine(x,z,h);
  const moonGlow=light(outside,0x80999a,20,-7,7,-16,30);
  // Dust motes and framed photographs make the room feel inhabited.
  box(room,'picture frame',-4.8,2.7,-1.5,.08,1.35,1.8,mat('frame',0x221f1c));box(room,'picture',-4.73,2.7,-1.5,.03,1.16,1.56,mat('picture',0x595449));
  cylinder(room,'rug',0,.015,2.2,2.5,2.5,.025,mat('rug',0x454239),32).scale.set(1,.3,.58);
}
buildRoom();

